def check_equation(a, b, c):
    """Checks the equation a^2*b^2 = 2*(a+b-c)*(b+c-a)*(c+a-b)"""
    # Ensure positive area, which means satisfying triangle inequality
    if not (a + b > c and b + c > a and c + a > b):
        return False

    lhs = a**2 * b**2
    rhs = 2 * (a + b - c) * (b + c - a) * (c + a - b)
    return lhs == rhs

solutions = []
limit = 10

# Iterate over integer side lengths a, b, c such that 1 <= a <= b <= c <= limit
for a in range(1, limit + 1):
    for b in range(a, limit + 1):
        for c in range(b, limit + 1):
            # Check triangle inequality first
            if a + b > c:
                if check_equation(a, b, c):
                    # Store the solution (sorted tuple for uniqueness)
                    solutions.append(tuple(sorted((a, b, c))))

print("Found solutions (a, b, c):")
for sol in sorted(list(set(solutions))):
    print(sol)

print("\nTotal unique solutions found:", len(set(solutions)))

import math
from itertools import combinations_with_replacement

def check_constraint(a, b, c):
    # Ensure it is a valid triangle
    if not (a + b > c and b + c > a and c + a > b):
        return False

    # Check the primary equation: a^2b^2 = 2(a + b - c)(b + c - a)(c + a - b)
    lhs = a**2 * b**2

    term1 = a + b - c
    term2 = b + c - a
    term3 = c + a - b

    rhs = 2 * term1 * term2 * term3

    return lhs == rhs

# Focused numerical search for integer-sided triangles with perimeter near 8.
# We search for sides up to 7, which covers P up to 21, but we filter heavily.
MAX_SIDE = 7
PERIMETER_TARGETS = [6, 7, 8, 9]
solutions_found = []

# Iterate over possible side lengths, assuming a <= b <= c
for a in range(1, MAX_SIDE + 1):
    for b in range(a, MAX_SIDE + 1):
        for c in range(b, MAX_SIDE + 1):
            P = a + b + c

            if P not in PERIMETER_TARGETS:
                continue

            if check_constraint(a, b, c):
                solutions_found.append((a, b, c, P))

print("Solutions found for integer-sided triangles near P=8:")
if solutions_found:
    for sol in solutions_found:
        print(f"Triangle: {sol[0]}, {sol[1]}, {sol[2]}, Perimeter: {sol[3]}")
else:
    print("No integer-sided solutions found for P in {6, 7, 8, 9}.")

